// @vitest-environment jsdom
// ABOUTME: Tests for watchDeploy — polling GitHub Actions runs for a pushed
// ABOUTME: commit and reporting the outcome through the activity log/toasts.
import { beforeEach, expect, it } from "vitest";
import type { GitHubApi, WorkflowRun } from "../../core/github/types";
import { GitHubError } from "../../core/github/types";
import { createAppStore } from "./state";
import { resetDeployWatchForTests } from "./state.deployActions";
import { buildFakeServices } from "./testing/fakes";

function instantWait(): Promise<void> {
  return Promise.resolve();
}

beforeEach(() => {
  resetDeployWatchForTests();
});

function workflowRun(overrides: Partial<WorkflowRun> = {}): WorkflowRun {
  return {
    name: "Deploy Eleventy site to Pages",
    status: "completed",
    conclusion: "success",
    htmlUrl: "https://github.com/obra/blog/actions/runs/1",
    ...overrides,
  };
}

/** Only listWorkflowRunsForSha is exercised by watchDeploy — the rest of
 *  GitHubApi is deliberately left unimplemented (see feature E's contract
 *  note for the same pattern). */
function fakeGithub(listWorkflowRunsForSha: GitHubApi["listWorkflowRunsForSha"]): GitHubApi {
  return { listWorkflowRunsForSha } as GitHubApi;
}

it("a successful run logs 'Live on blog.fsck.com' and toasts success", async () => {
  const run = workflowRun({ conclusion: "success", htmlUrl: "https://x/runs/1" });
  const github = fakeGithub(() => Promise.resolve([run]));
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha1");

  const log = store.getState().syncLog;
  expect(log).toHaveLength(1);
  expect(log[0]?.level).toBe("info");
  expect(log[0]?.message).toBe("Live on blog.fsck.com ✓");
  expect(log[0]?.detail).toBe("https://x/runs/1");
  const { toasts } = store.getState();
  expect(toasts).toHaveLength(1);
  expect(toasts[0]?.tone).toBe("success");
  expect(toasts[0]?.message).toBe("Live on blog.fsck.com");
});

it("a failed run logs an error with the run's URL and no toast", async () => {
  const run = workflowRun({ conclusion: "failure", htmlUrl: "https://x/runs/2" });
  const github = fakeGithub(() => Promise.resolve([run]));
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha2");

  const log = store.getState().syncLog;
  expect(log).toHaveLength(1);
  expect(log[0]?.level).toBe("error");
  expect(log[0]?.message).toBe("Deploy failed — the site still shows the previous version");
  expect(log[0]?.detail).toBe("https://x/runs/2");
  expect(store.getState().toasts).toHaveLength(0);
});

it("gives up after the poll budget with 'Couldn't find a deploy for this push'", async () => {
  const waitCalls: number[] = [];
  resetDeployWatchForTests({
    wait: (ms) => {
      waitCalls.push(ms);
      return instantWait();
    },
  });
  const github = fakeGithub(() => Promise.resolve([]));
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha3");

  const log = store.getState().syncLog;
  expect(log).toHaveLength(1);
  expect(log[0]?.level).toBe("info");
  expect(log[0]?.message).toBe("Couldn't find a deploy for this push");
  // ~4 minutes at a ~10s cadence = 24 attempts, waiting between each but not
  // after the last one => 23 waits of 10s.
  expect(waitCalls).toHaveLength(23);
  expect(waitCalls.every((ms) => ms === 10_000)).toBe(true);
});

it("a non-auth error after the first poll is a transient miss, not fatal", async () => {
  resetDeployWatchForTests({ wait: instantWait });
  let calls = 0;
  const run = workflowRun({ conclusion: "success", htmlUrl: "https://x/runs/3" });
  const github = fakeGithub(() => {
    calls += 1;
    if (calls === 1) {
      return Promise.resolve([]);
    }
    if (calls === 2) {
      return Promise.reject(new GitHubError("network", "temporary blip"));
    }
    return Promise.resolve([run]);
  });
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha4");

  const log = store.getState().syncLog;
  expect(log).toHaveLength(1);
  expect(log[0]?.message).toBe("Live on blog.fsck.com ✓");
});

it("an auth error on the first poll logs one warning, never toasts, and disables future watches", async () => {
  resetDeployWatchForTests({ wait: instantWait });
  let calls = 0;
  const github = fakeGithub(() => {
    calls += 1;
    return Promise.reject(new GitHubError("auth", "bad credentials"));
  });
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha5");
  // A later push (different sha) must not retry the request or re-log.
  await store.getState().watchDeploy("sha6");

  expect(calls).toBe(1);
  const log = store.getState().syncLog;
  expect(log).toHaveLength(1);
  expect(log[0]?.level).toBe("info");
  expect(log[0]?.message).toBe(
    "Deploy status is off: the token can't read GitHub Actions. Publishing still works — add the Actions read permission to see deploy progress.",
  );
  expect(store.getState().toasts).toHaveLength(0);
});

it("a network error on the very first poll is a transient miss, not a permission problem", async () => {
  resetDeployWatchForTests({ wait: instantWait });
  let calls = 0;
  const run = workflowRun({ conclusion: "success", htmlUrl: "https://x/runs/4" });
  const github = fakeGithub(() => {
    calls += 1;
    if (calls === 1) {
      return Promise.reject(new GitHubError("network", "offline for a moment"));
    }
    return Promise.resolve([run]);
  });
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha7");

  const log = store.getState().syncLog;
  expect(log).toHaveLength(1);
  expect(log[0]?.message).toBe("Live on blog.fsck.com ✓");
});

it("a first-poll failure never disables deploy watching for later pushes", async () => {
  resetDeployWatchForTests({ wait: instantWait });
  const run = workflowRun({ conclusion: "success", htmlUrl: "https://x/runs/5" });
  const github = fakeGithub((sha) => {
    if (sha === "sha-blip") {
      // Not a GitHubError at all — even a bare throw must not read as
      // "this token can't watch deploys".
      return Promise.reject(new Error("boom"));
    }
    return Promise.resolve([run]);
  });
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha-blip");
  await store.getState().watchDeploy("sha-next");

  const messages = store.getState().syncLog.map((entry) => entry.message);
  expect(messages).not.toContain(
    "Deploy status is off: the token can't read GitHub Actions. Publishing still works — add the Actions read permission to see deploy progress.",
  );
  expect(messages).toContain("Live on blog.fsck.com ✓");
});

it("reports a still-running deploy at timeout instead of claiming none was found", async () => {
  resetDeployWatchForTests({ wait: instantWait });
  const slowRun = workflowRun({
    status: "in_progress",
    conclusion: null,
    htmlUrl: "https://x/runs/9",
  });
  const github = fakeGithub(() => Promise.resolve([slowRun]));
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await store.getState().watchDeploy("sha-slow");

  const log = store.getState().syncLog;
  expect(log).toHaveLength(1);
  expect(log[0]?.level).toBe("info");
  expect(log[0]?.message).toBe("Deploy is still running — check the run on GitHub for the result");
  expect(log[0]?.detail).toBe("https://x/runs/9");
});

it("a second watchDeploy for the same sha while one is active is a no-op", async () => {
  resetDeployWatchForTests({ wait: instantWait });
  let calls = 0;
  const run = workflowRun({ conclusion: "success" });
  const github = fakeGithub(() => {
    calls += 1;
    return Promise.resolve([run]);
  });
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore({ ...services, github });

  await Promise.all([store.getState().watchDeploy("sha8"), store.getState().watchDeploy("sha8")]);

  expect(calls).toBe(1);
  expect(store.getState().syncLog).toHaveLength(1);
});

it("does nothing when services.github is null", async () => {
  const { services } = buildFakeServices({ withSync: false });
  const store = createAppStore(services);

  await store.getState().watchDeploy("sha9");

  expect(store.getState().syncLog).toHaveLength(0);
  expect(store.getState().toasts).toHaveLength(0);
});

// ABOUTME: watchDeploy — follows the GitHub Actions run for a just-pushed
// ABOUTME: commit and reports "live on the site" (or a failed build) through
// ABOUTME: the activity log. Wired from attachSync's log subscription.
import type { WorkflowRun } from "../../core/github/types";
import { GitHubError } from "../../core/github/types";
import { appendLog } from "./state.logActions";
import type { ActionCtx, DeployState } from "./state.types";

/** Poll cadence and overall budget: check roughly every 10s, give up after
 *  roughly 4 minutes (a stuck/slow Pages build shouldn't poll forever). */
const POLL_INTERVAL_MS = 10_000;
const TIMEOUT_MS = 240_000;
const MAX_ATTEMPTS = Math.ceil(TIMEOUT_MS / POLL_INTERVAL_MS);

type WaitFn = (ms: number) => Promise<void>;

function realWait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Swapped out in tests so the full poll loop runs without real delays —
 *  see resetDeployWatchForTests. */
let wait: WaitFn = realWait;

/** Shas currently being polled — a second watchDeploy for a sha already
 *  in flight is a no-op (checked synchronously before the first await). */
const activeWatches = new Set<string>();

/** Sticky for the app session once a poll fails with an auth error: never
 *  re-warn, never re-poll, on any later push. Module-level because ActionCtx
 *  (the only thing this action can thread state through) has no per-session
 *  bag of its own — see the feature C contract. */
let deployWatchDisabled = false;

function isAuthError(error: unknown): boolean {
  return error instanceof GitHubError && error.kind === "auth";
}

/** An auth error means this token can't watch deploys — log it once (ever)
 *  and stop. Only auth qualifies: any other failure (a network blip, a 5xx)
 *  says nothing about the token's scopes, and disabling on it would falsely
 *  and permanently blame the token for a transient hiccup. */
function disableDeployWatch(ctx: ActionCtx): void {
  if (deployWatchDisabled) {
    return;
  }
  deployWatchDisabled = true;
  appendLog(ctx, {
    level: "info",
    message:
      "Deploy status is off: the token can't read GitHub Actions. Publishing still works — add the Actions read permission to see deploy progress.",
  });
}

function findConcludedRun(runs: WorkflowRun[]): WorkflowRun | null {
  return runs.find((run) => run.status === "completed" && run.conclusion !== null) ?? null;
}

/** Updates the deploy state the Activity popover shows, but only while it's
 *  still about this push: an older push finishing late mustn't overwrite a
 *  newer one's "Deploying…". */
function setDeployState(ctx: ActionCtx, sha: string, state: DeployState["state"] | null): void {
  ctx.set((current) => {
    if (current.deploy?.sha !== sha) {
      return {};
    }
    return { deploy: state === null ? null : { sha, state, at: ctx.deps.now() } };
  });
}

/** Watching stopped with no answer (auth error, poll budget spent, a
 *  throw): never leave the popover saying "Deploying…" forever. */
function clearIfUnanswered(ctx: ActionCtx, sha: string): void {
  if (ctx.get().deploy?.state === "deploying") {
    setDeployState(ctx, sha, null);
  }
}

function reportConcludedRun(ctx: ActionCtx, run: WorkflowRun, sha: string): void {
  setDeployState(ctx, sha, run.conclusion === "success" ? "live" : "failed");
  if (run.conclusion === "success") {
    appendLog(ctx, { level: "info", message: "Live on blog.fsck.com ✓", detail: run.htmlUrl });
    ctx.get().addToast({ tone: "success", message: "Live on blog.fsck.com", source: "deploy" });
    return;
  }
  appendLog(ctx, {
    level: "error",
    message: "Deploy failed — the site still shows the previous version",
    detail: run.htmlUrl,
  });
}

/** The poll budget ran out — two very different stories: a run was found and
 *  is just slow (point at it; its outcome is unknowable from here), or no
 *  run ever showed up for this sha at all. */
function reportTimeout(ctx: ActionCtx, lastSeenRun: WorkflowRun | null): void {
  if (lastSeenRun) {
    appendLog(ctx, {
      level: "info",
      message: "Deploy is still running — check the run on GitHub for the result",
      detail: lastSeenRun.htmlUrl,
    });
    return;
  }
  appendLog(ctx, { level: "info", message: "Couldn't find a deploy for this push" });
}

async function watchDeploy(ctx: ActionCtx, commitSha: string): Promise<void> {
  if (deployWatchDisabled || activeWatches.has(commitSha)) {
    return;
  }
  const { github } = ctx.get().services;
  if (!github) {
    return;
  }
  activeWatches.add(commitSha);
  ctx.set({ deploy: { sha: commitSha, state: "deploying", at: ctx.deps.now() } });
  try {
    let lastSeenRun: WorkflowRun | null = null;
    for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt += 1) {
      let runs: WorkflowRun[];
      try {
        // biome-ignore lint/performance/noAwaitInLoops: each poll depends on the previous one's outcome (and the wait between them) — inherently sequential, not parallelizable.
        runs = await github.listWorkflowRunsForSha(commitSha);
      } catch (error) {
        if (isAuthError(error)) {
          disableDeployWatch(ctx);
          return;
        }
        runs = []; // transient miss (network blip, 5xx) — keep polling
      }
      lastSeenRun = runs[0] ?? lastSeenRun;
      const concluded = findConcludedRun(runs);
      if (concluded) {
        reportConcludedRun(ctx, concluded, commitSha);
        return;
      }
      if (attempt < MAX_ATTEMPTS - 1) {
        await wait(POLL_INTERVAL_MS);
      }
    }
    reportTimeout(ctx, lastSeenRun);
  } finally {
    activeWatches.delete(commitSha);
    clearIfUnanswered(ctx, commitSha);
  }
}

/** A failed deploy stays on the sync button (background pulls don't clear
 *  it) until a new push starts another deploy, or a sync the person asked
 *  for succeeds: Sync Now is the Error state's remedy. */
function clearFailedDeploy(ctx: ActionCtx): void {
  const { deploy, syncStatus } = ctx.get();
  if (deploy?.state === "failed" && syncStatus?.state !== "error") {
    ctx.set({ deploy: null });
  }
}

/** Test-only: clear dedupe/auth-warning state and optionally swap the wait
 *  function so the full poll loop runs without real delays. */
function resetDeployWatchForTests(overrides: { wait?: WaitFn } = {}): void {
  activeWatches.clear();
  deployWatchDisabled = false;
  wait = overrides.wait ?? realWait;
}

export { clearFailedDeploy, resetDeployWatchForTests, watchDeploy };

// ABOUTME: createConnect — saving a GitHub token: checked with GitHub before it
// ABOUTME: replaces the saved one, installed right away, first sync not awaited.
import { describe, expect, it, vi } from "vitest";
import type { GitHubApi } from "../core/github/types";
import { GitHubError } from "../core/github/types";
import type { Services } from "../core/services";
import { KEYCHAIN_TOKEN_KEY } from "../ui/app/state.types";
import { createFakeSync } from "../ui/app/testing/fakeSync";
import { buildFakeServices } from "../ui/app/testing/fakes";
import { ConnectError, createConnect } from "./connect";

function setup(options: { getRef?: () => Promise<unknown>; initialSync?: () => Promise<void> }) {
  const fake = buildFakeServices({ withSync: false });
  let current: Services = fake.services;
  const install = vi.fn((next: Services) => {
    current = next;
  });
  const github = {
    getRef: options.getRef ?? (() => Promise.resolve({ sha: "head" })),
  } as unknown as GitHubApi;
  const connect = createConnect({
    current: () => current,
    install,
    build: () => ({ github, sync: createFakeSync() }),
    initialSync: options.initialSync ?? (() => Promise.resolve()),
  });
  return { connect, install, shell: fake.shell, current: () => current };
}

describe("createConnect", () => {
  it("a token GitHub accepts is saved and installed", async () => {
    const { connect, install, shell } = setup({});
    await connect("good-token");
    expect(await shell.keychainGet(KEYCHAIN_TOKEN_KEY)).toBe("good-token");
    expect(install).toHaveBeenCalledTimes(1);
  });

  it("a token GitHub rejects leaves the saved token and the services alone", async () => {
    const { connect, install, shell } = setup({
      getRef: () => Promise.reject(new GitHubError("auth", "getRef: Bad credentials")),
    });
    await shell.keychainSet(KEYCHAIN_TOKEN_KEY, "old-good-token");
    await expect(connect("bad-token")).rejects.toBeInstanceOf(GitHubError);
    expect(await shell.keychainGet(KEYCHAIN_TOKEN_KEY)).toBe("old-good-token");
    expect(install).not.toHaveBeenCalled();
  });

  it("a keychain failure says so and installs nothing", async () => {
    const { connect, install, shell } = setup({});
    shell.keychainSet = () => Promise.reject(new Error("errSecAuthFailed"));
    await expect(connect("good-token")).rejects.toMatchObject({ kind: "keychain" });
    expect(install).not.toHaveBeenCalled();
  });

  it("returns once installed, without waiting for the first sync", async () => {
    let finishSync: () => void = () => undefined;
    const { connect, install } = setup({
      initialSync: () =>
        new Promise<void>((resolve) => {
          finishSync = resolve;
        }),
    });
    await connect("good-token");
    expect(install).toHaveBeenCalledTimes(1);
    finishSync();
  });

  it("refuses a second token while one is being checked", async () => {
    let answer: (value: unknown) => void = () => undefined;
    let calls = 0;
    const { connect } = setup({
      getRef: () => {
        calls += 1;
        return calls > 1
          ? Promise.resolve({ sha: "head" })
          : new Promise((resolve) => {
              answer = resolve;
            });
      },
    });
    const first = connect("one");
    await expect(connect("two")).rejects.toBeInstanceOf(ConnectError);
    answer({ sha: "head" });
    await first;
    await expect(connect("three")).resolves.toBeUndefined();
  });

  it("without a GitHub runtime (the browser demo) just saves the token", async () => {
    const fake = buildFakeServices({ withSync: false });
    const install = vi.fn();
    const connect = createConnect({
      current: () => fake.services,
      install,
      build: null,
      initialSync: () => Promise.resolve(),
    });
    await connect("demo-token");
    expect(await fake.shell.keychainGet(KEYCHAIN_TOKEN_KEY)).toBe("demo-token");
    expect(install).not.toHaveBeenCalled();
  });

  it("gives up on a token check after 20s, as offline, saving nothing", async () => {
    vi.useFakeTimers();
    const { connect, install, shell } = setup({ getRef: () => new Promise(() => undefined) });
    const attempt = (token: string) => connect(token).catch((failure: unknown) => failure);
    const first = attempt("slow-token");
    await vi.advanceTimersByTimeAsync(20_000);
    expect(await first).toMatchObject({ kind: "network" });
    expect(await shell.keychainGet(KEYCHAIN_TOKEN_KEY)).toBeNull();
    expect(install).not.toHaveBeenCalled();
    // Not stuck "connecting": the next token gets its own check.
    const second = attempt("next-token");
    await vi.advanceTimersByTimeAsync(20_000);
    expect(await second).toBeInstanceOf(GitHubError);
    vi.useRealTimers();
  });

  it("starts a new token's first download only after the last one finished", async () => {
    const started: string[] = [];
    let finishFirst: () => void = () => undefined;
    const { connect } = setup({
      initialSync: () => {
        started.push(`sync ${started.length + 1}`);
        return started.length === 1
          ? new Promise<void>((resolve) => {
              finishFirst = resolve;
            })
          : Promise.resolve();
      },
    });
    await connect("token-a");
    await connect("token-b");
    await Promise.resolve();
    expect(started).toEqual(["sync 1"]);
    finishFirst();
    await vi.waitFor(() => expect(started).toEqual(["sync 1", "sync 2"]));
  });
});

// ABOUTME: runInitialSync's contract: first run bootstraps (read-only), every
// ABOUTME: later launch pulls — launching the app must never push/deploy.
import { expect, it } from "vitest";
import { META_LAST_ROOT_TREE_SHA } from "../core/sync/meta";
import { buildFakeServices } from "../ui/app/testing/fakes";
import { runInitialSync } from "./index";

it("first run (empty store) bootstraps and does not sync", async () => {
  const fake = buildFakeServices();

  await runInitialSync(fake.services);

  expect(fake.sync?.bootstrapCallCount()).toBe(1);
  expect(fake.sync?.syncCallCount()).toBe(0);
});

it("a routine launch pulls remote changes but never pushes", async () => {
  const fake = buildFakeServices();
  await fake.services.store.setMeta(META_LAST_ROOT_TREE_SHA, "some-tree-sha");

  await runInitialSync(fake.services);

  // Unpushed work from the last session must stay pending until the user
  // syncs — relaunching with half-finished edits to a published post must
  // not deploy them.
  expect(fake.sync?.pullCallCount()).toBe(1);
  expect(fake.sync?.syncCallCount()).toBe(0);
  expect(fake.sync?.bootstrapCallCount()).toBe(0);
});

it("no sync configured: a no-op", async () => {
  const fake = buildFakeServices({ withSync: false });

  await runInitialSync(fake.services);
});

// @vitest-environment jsdom
// ABOUTME: detectPlatform / applyPlatformAttribute — the pre-render platform
// ABOUTME: probe that picks the Mac look, with a safe "web" fallback.
import { describe, expect, it, vi } from "vitest";
import {
  applyGlassAttribute,
  applyPlatformAttribute,
  detectGlass,
  detectPlatform,
} from "./platform";

describe("detectPlatform", () => {
  it("is web outside Tauri, without calling the bridge", async () => {
    const invoke = vi.fn();
    expect(await detectPlatform({ isTauri: () => false, invoke })).toBe("web");
    expect(invoke).not.toHaveBeenCalled();
  });

  it("asks the Rust side inside Tauri", async () => {
    const invoke = vi.fn().mockResolvedValue("macos");
    expect(await detectPlatform({ isTauri: () => true, invoke })).toBe("macos");
    expect(invoke).toHaveBeenCalledWith("current_platform");
  });

  it("maps desktop platforms we don't style natively to web", async () => {
    const invoke = vi.fn().mockResolvedValue("windows");
    expect(await detectPlatform({ isTauri: () => true, invoke })).toBe("web");
  });

  it("falls back to web, and says so, when the command fails", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => undefined);
    const invoke = vi.fn().mockRejectedValue(new Error("bridge not ready"));
    expect(await detectPlatform({ isTauri: () => true, invoke })).toBe("web");
    expect(warn).toHaveBeenCalledWith(
      "current_platform failed; using the web look",
      expect.any(Error),
    );
    warn.mockRestore();
  });
});

describe("applyPlatformAttribute", () => {
  it("writes data-platform on the root element", () => {
    const root = document.createElement("html");
    applyPlatformAttribute(root, "macos");
    expect(root.getAttribute("data-platform")).toBe("macos");
  });
});

describe("detectGlass", () => {
  it("is off off macOS, without asking", async () => {
    const invoke = vi.fn();
    expect(await detectGlass("web", invoke)).toBe(false);
    expect(await detectGlass("ios", invoke)).toBe(false);
    expect(invoke).not.toHaveBeenCalled();
  });

  it("asks Rust on macOS", async () => {
    const invoke = vi.fn().mockResolvedValue(true);
    expect(await detectGlass("macos", invoke)).toBe(true);
    expect(invoke).toHaveBeenCalledWith("glass_active");
  });

  it("treats a failed or odd answer as off (opaque is always safe)", async () => {
    expect(await detectGlass("macos", vi.fn().mockRejectedValue(new Error("no")))).toBe(false);
    expect(await detectGlass("macos", vi.fn().mockResolvedValue("yes"))).toBe(false);
  });
});

describe("applyGlassAttribute", () => {
  it("writes data-glass on the root element", () => {
    const root = document.createElement("html");
    applyGlassAttribute(root, true);
    expect(root.getAttribute("data-glass")).toBe("on");
    applyGlassAttribute(root, false);
    expect(root.getAttribute("data-glass")).toBe("off");
  });
});

// ABOUTME: Tests for fetchPageTitle's security-relevant guards — the
// ABOUTME: loopback/private-host blocklist and the byte-capped body read —
// ABOUTME: plus its ordinary title-extraction behavior, against a mocked
// ABOUTME: @tauri-apps/plugin-http so no real Tauri runtime is needed.
import { beforeEach, describe, expect, it, vi } from "vitest";

const tauriFetchMock = vi.fn();
vi.mock("@tauri-apps/plugin-http", () => ({
  fetch: (...args: unknown[]) => tauriFetchMock(...args),
}));

// Imported after the mock is registered (vi.mock is hoisted above imports).
const { fetchPageTitle } = await import("./fetchTitle");

function htmlResponse(html: string, contentType = "text/html; charset=utf-8"): Response {
  return {
    ok: true,
    headers: { get: (name: string) => (name === "content-type" ? contentType : null) },
    text: () => Promise.resolve(html),
    body: null,
  } as unknown as Response;
}

function streamingHtmlResponse(html: string, contentType = "text/html"): Response {
  const bytes = new TextEncoder().encode(html);
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      // Deliver in small chunks so a cap mid-stream is exercised, not just
      // a single big chunk.
      const chunkSize = 64;
      for (let i = 0; i < bytes.length; i += chunkSize) {
        controller.enqueue(bytes.slice(i, i + chunkSize));
      }
      controller.close();
    },
  });
  return {
    ok: true,
    headers: { get: (name: string) => (name === "content-type" ? contentType : null) },
    text: () => Promise.resolve(html),
    body: stream,
  } as unknown as Response;
}

beforeEach(() => {
  tauriFetchMock.mockReset();
});

describe("fetchPageTitle — loopback/private-host blocklist", () => {
  const disallowed = [
    "https://localhost/status",
    "https://127.0.0.1/status",
    "https://127.55.0.9/status",
    "https://0.0.0.0/",
    "https://192.168.1.1/admin",
    "https://10.0.0.5/x",
    "https://172.16.0.1/x",
    "https://172.31.255.255/x",
    "https://169.254.169.254/latest/meta-data/",
    "https://nas.local/admin",
    "https://[::1]/x",
    "https://[fe80::1]/x",
    "https://[fc00::1]/x",
  ];

  it.each(disallowed)("never calls the underlying fetch for %s", async (url) => {
    const result = await fetchPageTitle(url);
    expect(result).toBeNull();
    expect(tauriFetchMock).not.toHaveBeenCalled();
  });

  it("does not block an ordinary internet host with '.local'-like but distinct suffix", async () => {
    tauriFetchMock.mockResolvedValue(htmlResponse("<title>Fine</title>"));
    const result = await fetchPageTitle("https://notlocalatall.example.com/post");
    expect(result).toBe("Fine");
    expect(tauriFetchMock).toHaveBeenCalledTimes(1);
  });

  it("still fetches an ordinary public host", async () => {
    tauriFetchMock.mockResolvedValue(htmlResponse("<title>A Real Post</title>"));
    const result = await fetchPageTitle("https://example.com/post");
    expect(result).toBe("A Real Post");
    expect(tauriFetchMock).toHaveBeenCalledTimes(1);
  });

  it("resolves null (never throws) for an unparseable URL", async () => {
    await expect(fetchPageTitle("not a url")).resolves.toBeNull();
    expect(tauriFetchMock).not.toHaveBeenCalled();
  });
});

describe("fetchPageTitle — capped body read", () => {
  it("extracts a title that appears within the byte cap", async () => {
    const html = `<html><head><title>Early Title</title></head><body>${"x".repeat(1000)}</body></html>`;
    tauriFetchMock.mockResolvedValue(streamingHtmlResponse(html));
    const result = await fetchPageTitle("https://example.com/post");
    expect(result).toBe("Early Title");
  });

  it("does not hang or crash on a response far larger than the cap, and does not read past it", async () => {
    // A title placed well past 256 KiB must not be found — proving the read
    // actually stopped, not just that extraction happened to work anyway.
    const filler = "x".repeat(300_000);
    const html = `<html><head></head><body>${filler}<title>Buried Title</title></body></html>`;
    tauriFetchMock.mockResolvedValue(streamingHtmlResponse(html));
    const result = await fetchPageTitle("https://example.com/post");
    expect(result).toBeNull();
  });

  it("falls back to a truncated text() read when the Response exposes no body stream", async () => {
    const filler = "x".repeat(300_000);
    const html = `<html><head></head><body>${filler}<title>Buried Title</title></body></html>`;
    tauriFetchMock.mockResolvedValue(htmlResponse(html));
    const result = await fetchPageTitle("https://example.com/post");
    expect(result).toBeNull();
  });
});

describe("fetchPageTitle — ordinary failure modes still resolve null", () => {
  it("returns null on a non-2xx status", async () => {
    tauriFetchMock.mockResolvedValue({
      ok: false,
      headers: { get: () => "text/html" },
      text: () => Promise.resolve(""),
      body: null,
    });
    expect(await fetchPageTitle("https://example.com/missing")).toBeNull();
  });

  it("returns null for a non-HTML content type", async () => {
    tauriFetchMock.mockResolvedValue(htmlResponse("{}", "application/json"));
    expect(await fetchPageTitle("https://example.com/data.json")).toBeNull();
  });

  it("returns null (never rejects) when the underlying fetch throws", async () => {
    tauriFetchMock.mockRejectedValue(new Error("network error"));
    await expect(fetchPageTitle("https://example.com/post")).resolves.toBeNull();
  });
});

